<?php
declare(strict_types=1);final class AIService{static function run(string $task,string $text,string $lang):string{$url=(string)config('LLM_API_URL','');$key=(string)config('LLM_API_KEY','');if(!$url||!$key)throw new RuntimeException('AI provider not configured.');$tasks=['summary'=>'Summarise with key takeaways.','chapters'=>'Create chapters without inventing timestamps.','translate'=>'Translate into '.$lang.'.','linkedin'=>'Write a LinkedIn post.','blog'=>'Write a blog article.','newsletter'=>'Write a newsletter.','twitter'=>'Write an X thread.','instagram'=>'Write an Instagram caption.','youtube'=>'Write a YouTube description.','reddit'=>'Write a Reddit post.','tiktok'=>'Write a short video script.'];if(!isset($tasks[$task]))throw new InvalidArgumentException('Unknown AI task.');$body=['model'=>config('LLM_MODEL',''),'messages'=>[['role'=>'system','content'=>'Be accurate. Do not invent facts or timestamps.'],['role'=>'user','content'=>$tasks[$task]."\nUse only this transcript:\n".mb_substr($text,0,90000)]]];$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($body),CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>180,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$key]]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$r=json_decode((string)$raw,true)?:[];if(!$raw||$code<200||$code>=300)throw new RuntimeException('AI provider HTTP '.$code);$out=$r['choices'][0]['message']['content']??'';if(!$out)throw new RuntimeException('AI provider returned empty content.');return $out;}}
